INSERT OR IGNORE INTO lessons (id,family_id,seed_key,title,stage,learning_area,unit_id,status,data,created_at,updated_at)
SELECT 'seed-'||k,NULL,k,'Year '||y||', Week '||wk||', Lesson '||ln||': '||tt,'S4',strand,NULL,'approved',json_object('year_level','Year '||y,'subject',strand,'unit_title',unit,'unit_number',un,'week',wk,'week_in_unit',uw,'lesson_number',ln,'lesson_role',CASE ln WHEN 1 THEN 'Investigate' ELSE 'Apply and respond' END,'learning_intention',CASE ln WHEN 1 THEN 'Investigate lesson in the unit '||unit||'. Focus: '||tt||'. Students explore evidence, sources, maps and perspectives.' ELSE 'Apply and respond lesson in the unit '||unit||'. Focus: '||tt||'. Students analyse, compare, create or communicate a reasoned response.' END||CASE WHEN uw=uweeks THEN ' This is the showcase and consolidation week for the unit.' ELSE '' END,'outcome_codes',json('[]'),'coming_soon',json('true'),'source_note','Coming soon. This is a planned lesson card. Outcome codes are not assigned yet: map this lesson to the relevant NESA History or Geography 7–10 Stage 4 syllabus before it is built. Check First Nations content with appropriate community sources.'),'2026-10-11T10:00:00Z','2026-10-11T10:00:00Z' FROM x;
